// src/App.js
import React, { useState, useEffect } from 'react';
import { GoogleOAuthProvider, GoogleLogin } from '@react-oauth/google';
import { jwtDecode } from "jwt-decode";
import axios from 'axios';
import { MapContainer, TileLayer, GeoJSON } from 'react-leaflet';
import worldGeoJSON from './world.geo.json';
import './App.css';

const GOOGLE_CLIENT_ID = "569893946999-hlv7lda6iquvtn13b3icnf9ldu5o3ici.apps.googleusercontent.com";
const BACKEND_URL = "http://localhost:8000";

// --- 1. NEW LEGEND COMPONENT ---
// This component will display the map legend.
const Legend = ({ max, label }) => {
    if (!max) return null; // Don't show legend if there's no data

    const grades = [0, 0.2, 0.4, 0.6, 0.8].map(p => Math.round(p * max));
    const getColor = (value) => {
        const intensity = value / max;
        if (intensity > 0.8) return '#800026';
        if (intensity > 0.6) return '#BD0026';
        if (intensity > 0.4) return '#E31A1C';
        if (intensity > 0.2) return '#FC4E2A';
        return '#FD8D3C';
    };

    return (
        <div className="legend">
            <h4>{label || 'Legend'}</h4>
            {grades.map((grade, index) => (
                <div key={index} className="legend-item">
                    <i style={{ background: getColor(grade) }}></i>
                    {grade.toLocaleString()} {grades[index + 1] ? `– ${grades[index + 1].toLocaleString()}` : '+'}
                </div>
            ))}
        </div>
    );
};

function App() {
    const [user, setUser] = useState(null);
    const [query, setQuery] = useState('');
    const [mapData, setMapData] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSearch = async (e) => {
        e.preventDefault();
        if (!user) return;
        setLoading(true);
        setError('');
        setMapData([]);

        try {
            const response = await axios.post(`${BACKEND_URL}/api/query`, { query });
            console.log("Data received from backend:", response.data); // For debugging
            setMapData(response.data);
        } catch (err) {
            const errorMsg = err.response?.data?.detail || "An unexpected error occurred.";
            setError(errorMsg);
            console.error("Error fetching data:", errorMsg); // For debugging
        } finally {
            setLoading(false);
        }
    };

    // --- 2. IMPROVED MAP STYLING LOGIC ---
    const dataMap = new Map(mapData.map(item => [item.country_code, item.value]));
    const validValues = mapData.map(item => item.value || 0).filter(v => isFinite(v));
    const maxValue = validValues.length > 0 ? Math.max(...validValues) : 0;
    const mapLabel = mapData.length > 0 ? mapData[0].label : '';

    const getColor = (value) => {
        if (value === null || value === undefined || maxValue === 0) {
            return '#CCCCCC'; // Gray for no data
        }
        const intensity = value / maxValue;
        if (intensity > 0.8) return '#800026';
        if (intensity > 0.6) return '#BD0026';
        if (intensity > 0.4) return '#E31A1C';
        if (intensity > 0.2) return '#FC4E2A';
        return '#FD8D3C';
    };

    const mapStyle = (feature) => ({
        fillColor: getColor(dataMap.get(feature.id)),
        weight: 1,
        opacity: 1,
        color: 'white',
        fillOpacity: 0.7
    });

    return (
        <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>
            <div className="app-container">
                <div className="top-bar">
                    <h1>DataMap</h1>
                    <div className="search-area">
                        {user && (
                            <form onSubmit={handleSearch}>
                                <input
                                    type="text"
                                    value={query}
                                    onChange={(e) => setQuery(e.target.value)}
                                    placeholder="e.g., Which countries have the highest GDP?"
                                />
                                <button type="submit" disabled={loading}>
                                    {loading ? '...' : 'Search'}
                                </button>
                            </form>
                        )}
                    </div>
                    <div className="login-area">
                        {user ? (
                            <div className="welcome-message">Welcome, {user.given_name}!</div>
                        ) : (
                            <GoogleLogin
                                onSuccess={(res) => setUser(jwtDecode(res.credential))}
                                onError={() => console.log('Login Failed')}
                            />
                        )}
                    </div>
                </div>

                {error && <div className="error-banner">{error}</div>}

                <MapContainer center={[20, 0]} zoom={2} style={{ height: '100vh', width: '100%', zIndex: 0 }}>
                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                    <GeoJSON
                        key={JSON.stringify(mapData)}
                        data={worldGeoJSON}
                        style={mapStyle}
                        onEachFeature={(feature, layer) => {
                            const value = dataMap.get(feature.id);
                            // 3. FIX POPUP LABEL
                            layer.bindPopup(`<strong>${feature.properties.name}</strong><br/>${mapLabel}: ${value ? value.toLocaleString() : 'No data'}`);
                        }}
                    />
                    {/* 4. RENDER THE LEGEND ON THE MAP */}
                    <Legend max={maxValue} label={mapLabel} />
                </MapContainer>
            </div>
        </GoogleOAuthProvider>
    );
}

export default App;
